/* =====================================================================
   SCREENS — each: role, title, route, purpose, reads, api, states, rules, render()
   API paths are the platform's own routes (global prefix /api/v1).
   ===================================================================== */
const SCREENS={};
const def=(id,o)=>{SCREENS[id]=Object.assign({id},o)};
const pill=s=>`<span class="pill st-${String(s).toLowerCase()}">${esc(s)}</span>`;
const tp=(t,tone='off')=>`<span class="pill t-${tone}">${esc(t)}</span>`;
const head=(t,p,right='')=>`<div class="phead"><div><h3>${t}</h3>${p?`<p>${p}</p>`:''}</div>${right}</div>`;
const kv=(k,v)=>`<div class="kv"><span>${k}</span><b>${v}</b></div>`;
const empty=(ic,t,p,btn='')=>`<div class="empty"><span class="ei">${I(ic)}</span><b>${t}</b><span>${p}</span>${btn}</div>`;
const card=(title,sub,inner,right='')=>`<div class="card"><div class="row sb" style="align-items:flex-start"><div class="grow"><h4>${title}</h4>${sub?`<p class="sub">${sub}</p>`:''}</div>${right}</div>${inner}</div>`;
const logo=id=>`<span class="logo" style="background:${SUP[id].tint}">${SUP[id].mark}</span>`;
function waitFor(stageIdx,what){const n=nextStep();
  return empty('lock',what,`This fills in when the order reaches ${STAGES[stageIdx].name.toLowerCase()}. Next thing to do: ${n.t.toLowerCase()}.`,`<button class="btn pri sm" data-go="${n.go}">${esc(n.b)}${I('arrow')}</button>`)}
function pipeHtml(steps){return `<div class="pipe">${steps.map(([t,p,st],i)=>`<div class="ps ${st}"><span class="pd">${st==='done'?I('check'):i+1}</span><div><div class="pt">${esc(t)}</div><div class="pp">${esc(p)}</div></div></div>`).join('')}</div>`}
const stampHtml=(txt,iso,gold,big,isNew)=>`<span class="stamp ${gold?'gold':''} ${big?'big':''} ${isNew?'in':''}"><span>${esc(txt)}<em>${dmy(iso.slice(0,10))}</em></span></span>`;

const NAVS={
  sup:[['s.chat','chat','Chats',()=>S.unread.sup],['s.quote','rupee','Quote',()=>S.rfq.status==='sent'&&S.rfq.to.includes('ganesh')&&!S.rfq.quotes.ganesh?1:0],['s.record','award','My record'],['s.cap','flame','Capacity']],
  own:[['w.inbox','inbox','Needs you',()=>S.po&&S.po.status==='awaiting'?1:0],['w.today','list','Today',()=>S.unread.own],['w.biz','chart','Business']],
  floor:[['m.jobs','list','Jobs'],['m.wo','clipboard','Work order',()=>S.inspection==='pass'&&!(S.wo&&S.wo.status==='done')?1:0],['m.mat','box','Materials']]
};
const TABS={
  pur:[['p.home','home','Today'],['p.sales','file','Sales order',()=>S.order==='received'?1:0],['p.plan','chart','Material check'],['p.net','net','Supplier network',()=>S.rfq.status==='sent'?Object.keys(S.rfq.quotes).length:0],['p.po','cart','Purchase orders',()=>S.po&&S.po.status==='awaiting'?1:0],['p.rec','award','Supplier records'],['p.log','list','Activity']],
  stores:[['t.gate','truck','Gate',()=>S.po&&S.po.status==='approved'&&(!S.grn||S.grn.pending)?1:0],['t.qc','shield','Inspection',()=>S.grn&&!S.grn.pending&&S.inspection!=='pass'?1:0],['t.stock','box','Stock'],['t.rec','award','Supplier records']],
  acct:[['a.dispatch','truck','Dispatch & invoice',()=>S.wo&&S.wo.status==='done'&&!(S.dispatch&&S.dispatch.irn)?1:0],['a.books','book','Ledger'],['a.audit','lock','Audit trail']]
};

/* ================= PURCHASE (Priya, laptop) ================= */
function routeCard(){const c=current();
  return `<div class="route"><div class="route-h"><h4>Route card</h4><span class="doc">${ORDER.no}</span><span class="sub">${ORDER.qty} × ${esc(ORDER.item)} for ${esc(CUSTOMER.name)} · due ${dmyy(ORDER.due)}</span><span class="grow"></span>${S.closed?tp('Closed','gold'):tp('Station '+(c+1)+' of 9','acc')}</div>
  <div class="cells">${STAGES.map((s,i)=>{const done=stageDone(i),now=i===c;const go=['p.sales','p.plan','p.net','p.net','w.po','t.gate','m.wo','a.dispatch','a.books'][i];
    return `<button class="cell ${now?'now':''} ${!done&&!now?'locked':''}" data-go="${go}" aria-label="${esc(s.name)}${done?', done':now?', current':''}"><span class="n">${String(i+1).padStart(2,'0')}</span><b>${esc(s.name)}</b><small>${esc(s.who)}</small>${done?stampHtml(i===8?'Closed':'Done',S.stamped[i],i===8,false,S.justStamped===i):''}</button>`}).join('')}</div></div>`}
def('p.home',{role:'pur',title:'Today',route:'/',purpose:'Priya’s day at a glance: the one order moving through the factory, its route card with a stamp per finished station, what the next move is, and who the order is waiting on.',
  reads:['Sales order + its nine station states','Open RFQs, POs awaiting approval, expected receipts','Planning exceptions'],api:[['Order','GET /api/v1/sales/orders/{id}'],['Exceptions','GET /api/v1/planning/exceptions/summary'],['Open RFQs','GET /api/v1/purchase/rfqs?status=open']],
  states:['morning (nothing done)','waiting on supplier','waiting on owner','all stations stamped'],rules:['One database: every module reads the same order','A station is stamped by the event that finishes it, never by hand','“Waiting on others” lists people, not modules'],
  render(){const c=current(),n=nextStep();const hr=new Date(S.clock).getHours();const hi=hr<12?'Good morning':hr<17?'Good afternoon':'Good evening';const left=days(clockDate(),ORDER.due);
    const waiting=[];
    if(S.rfq.status==='sent'){const miss=S.rfq.to.filter(id=>!S.rfq.quotes[id]);if(miss.length)waiting.push(['Waiting on '+miss.length+' supplier'+(miss.length>1?'s':''),miss.map(id=>SUP[id].short).join(', ')+' · reply by '+dmy(RFQ.replyBy),'msg'])}
    if(S.po&&S.po.status==='awaiting')waiting.push(['Waiting on Arun',S.po.no+' · '+inr(S.po.exGst)+' · above your limit','shield']);
    if(S.po&&S.po.status==='approved'&&!S.grn)waiting.push(['Waiting on '+SUP[S.po.sup].short,NEED_QTY+' castings promised for '+dmy(S.po.promised),'truck']);
    if(S.wo&&S.wo.status!=='done')waiting.push(['Waiting on the shop floor',S.wo.no+' · '+(S.wo.status==='issued'?'assembling':'final test'),'factory']);
    return `${head(hi+', Priya.','One order is moving through the factory. Every module you open is looking at the same record.')}
    ${routeCard()}
    <div class="kpis"><div class="kpi hl"><b>${cu(INVOICE_TOTAL,'inr')}</b><span>order value, incl. IGST</span></div><div class="kpi"><b>${dmy(ORDER.due)}</b><span>due to ship · ${left>0?left+' days away':'today'}</span></div><div class="kpi"><b>${S.planRun?(S.inspection==='pass'?'0':'1'):'—'}</b><span>${S.planRun?(S.inspection==='pass'?'short parts · all covered':NEED_QTY+' pump bodies short'):'run planning to find out'}</span></div><div class="kpi"><b>${Object.keys(S.stamped).length} / 9</b><span>stations stamped</span></div></div>
    <div class="two"><div class="hero"><span class="eyb">${n.done?'Done':'Next · station '+(c+1)}</span><h4>${esc(n.t)}</h4><p>${n.done?'Typed once, carried through nine stations. Start over to run it again.':'XELOR suggests the next move. You decide.'}</p><div><button class="btn gold sm" data-go="${n.go}">${esc(n.b)}${I('arrow')}</button></div></div>
    ${card('Waiting on others',null,waiting.length?`<div class="list">${waiting.map(w=>`<div class="act"><span class="ai g">${I(w[2])}</span><div class="grow"><b style="color:var(--ink);font-size:13.5px">${esc(w[0])}</b><div class="sub">${esc(w[1])}</div></div></div>`).join('')}</div>`:`<p class="sub">Nobody. The next move is yours.</p>`)}</div>`}});

def('p.sales',{role:'pur',title:'Sales order',route:'/sales/orders/SO-2627-0291',purpose:'The customer’s PO, entered once. The credit check runs before confirming, not at dispatch. Confirming makes the order visible to planning, stores, production and accounts.',
  reads:['Customer master + GSTIN','Outstanding receivables','Item, HSN, price list'],api:[['Order','GET /api/v1/sales/orders/{id}'],['Outstanding','GET /api/v1/accounts/customers/{id}/outstanding'],['Confirm','POST /api/v1/sales/orders/{id}/confirm (Idempotency-Key)']],
  states:['received (draft)','credit within limit','credit over limit (blocked)','confirmed'],rules:['Credit is checked before confirming','IGST when supply crosses a state; CGST+SGST within','Confirming twice does nothing (idempotency key)'],
  render(){const after=CUSTOMER.outstanding+INVOICE_TOTAL,ok=S.order!=='received',pct=Math.round(after/CUSTOMER.limit*100);
    return `${head('Sales order',ok?'Confirmed. Every other module reads this record. It was typed once.':'The customer’s PO arrived by email. Check it and confirm. This is the only time anyone types it.')}
    <div class="two"><div class="docsheet"><div class="dh"><div><h4>Sales order</h4><div class="no">${ORDER.no} · against ${ORDER.custPo}</div></div>${ok?stampHtml('Confirmed',S.stamped[0],false,true,S.justStamped===0):tp('Not confirmed','warn')}</div>
      <div class="parties"><div><small>Customer</small><b>${esc(CUSTOMER.name)}</b><br>${esc(CUSTOMER.town)}<br><span class="mono" style="font-size:11px">${CUSTOMER.gstin}</span></div><div><small>Ship by</small><b>${dmyy(ORDER.due)}</b><br>${CUSTOMER.km} km by road<br>Payment ${CUSTOMER.terms} days</div></div>
      <div class="scx"><table class="tbl"><thead><tr><th>Item</th><th class="r">Qty</th><th class="r">Rate</th><th class="r">Amount</th></tr></thead><tbody>
      <tr><td><b>${esc(ORDER.item)}</b><div class="s mono">${ORDER.code} · HSN ${ORDER.hsn}</div></td><td class="r num">${ORDER.qty}</td><td class="r num">${inr(ORDER.price)}</td><td class="r num">${inr(TAXABLE)}</td></tr>
      <tr><td colspan="3" class="r s">IGST 18% · Karnataka to Andhra Pradesh</td><td class="r num">${inr(IGST)}</td></tr>
      <tr class="tot"><td colspan="3" class="r">Total</td><td class="r num">${inr(INVOICE_TOTAL)}</td></tr></tbody></table></div>
      ${ok?'':`<button class="btn pri" data-a="confirmOrder">${I('check')}Confirm order</button>`}</div>
    <div class="card"><h4>Credit check</h4><p class="sub">Done before confirming, not at dispatch</p>${kv('Credit limit',inr(CUSTOMER.limit))}${kv('Already owed',inr(CUSTOMER.outstanding))}${kv('This order',inr(INVOICE_TOTAL))}${kv('After this order',inr(after))}
      <div class="bar" style="grid-template-columns:minmax(0,1fr) 50px"><span class="tr"><i style="width:${pct}%;background:var(--green)"></i></span><b>${pct}%</b></div>${tp('Within limit','ok')}</div></div>
`}});

def('p.plan',{role:'pur',title:'Material check',route:'/planning/mrp/runs/latest',purpose:'XELOR explodes the confirmed order through its bill of materials and compares every part with this morning’s shelf. A shortage becomes a suggestion to ask suppliers, with the evidence written under it.',
  reads:['BOM v4 for KP-PMP-6ES','Stock by bin','Machining and assembly lead time'],api:[['Run MRP','POST /api/v1/planning/mrp/run'],['Explain a line','GET /api/v1/planning/mrp/runs/{runNo}/explain/{itemCode}'],['Exceptions','GET /api/v1/planning/exceptions']],
  states:['no confirmed order','ready to plan','short parts found','all covered'],rules:['Shortage = need − on shelf; never a guess','Need date = ship date − 11 days to machine and assemble','XELOR suggests; the planner decides'],
  render(){if(S.order==='received')return head('Material check','What the order needs, part by part, against the shelf.')+waitFor(0,'No confirmed order to plan yet');
    if(!S.planRun)return head('Material check','What '+ORDER.qty+' pumps need, part by part, against what is on the shelf this morning.')+empty('chart',ORDER.no+' is ready to plan','XELOR explodes the pump into its six parts and checks each against stock.',`<button class="btn pri" data-a="runPlan">${I('chart')}Check materials</button>`);
    const rows=BOM.map(b=>{const need=ORDER.qty*b.per,have=b.stock+(b===SHORT&&S.inspection==='pass'?NEED_QTY:0);return{b,need,have,short:Math.max(0,need-have)}});
    return `${head('Material check',`What ${ORDER.qty} pumps need, part by part, against the shelf. From BOM version 4.`)}
    <div class="scx"><table class="tbl"><thead><tr><th>Part</th><th class="r">Per pump</th><th class="r">Needed</th><th class="r">On shelf</th><th class="r">Short</th><th>Status</th></tr></thead><tbody>
    ${rows.map(r=>`<tr class="${r.short?'hot':''}"><td><b>${esc(r.b.name)}</b><div class="s mono">${r.b.code} · bin ${r.b.bin}</div></td><td class="r num">${r.b.per}</td><td class="r num">${nos(r.need)}</td><td class="r num">${nos(r.have)}</td><td class="r num"><b>${r.short?nos(r.short):'—'}</b></td><td>${r.short?tp('Short','bad'):tp('Covered','ok')}</td></tr>`).join('')}</tbody></table></div>
    ${S.inspection==='pass'?`<div class="card ok"><h4>Covered</h4><p class="sub">The 60 castings arrived and passed inspection, so every part is on the shelf.</p></div>`:
    `<div class="card gold"><div class="eyb" style="color:var(--gold-ink)">${I('spark')} Suggestion</div><h4>Ask three casting suppliers for ${NEED_QTY} pump bodies</h4><p class="sub">To ship on ${dmy(ORDER.due)} the castings must be here by ${dmy(RFQ.need)}. Three foundries on the network pour grey iron.</p>
      <div class="btns" style="justify-content:flex-start">${S.rfq.status==='none'?`<button class="btn pri sm" style="flex:0 0 auto" data-go="p.net">${I('send')}Ask suppliers for a price</button>`:`${tp('Request already sent','ok')} <button class="btn gh sm" style="flex:0 0 auto" data-go="p.net">See the answers</button>`}</div></div>`}`}});

function packCard(){const rows=[['Part',SHORT.name+', 6 in','item master '+SHORT.code],['Quantity',NEED_QTY+' nos','material check: 80 needed − '+SHORT.stock+' on shelf'],['Needed by',dmyy(RFQ.need),'ship '+dmy(ORDER.due)+' − 11 days'],['Drawing','Rev A, machining allowance 3 mm','item attachments'],['Checked on arrival',QPLAN.checks.length+' checks, sample '+QPLAN.sample,QPLAN.no],['Deliver to',FACTORY.town,'factory master']];
  return card('The request, already written','Priya typed nothing below',`<div class="list" style="gap:0">${rows.map((r,i)=>`<div class="kv" style="animation:scrin .4s var(--ease) ${i*60}ms both"><span>${esc(r[0])}</span><b>${esc(r[1])}<span class="mono" style="display:block;font-size:10px;color:var(--muted);font-weight:500">from ${esc(r[2])}</span></b></div>`).join('')}</div>`)}
function rfqBubble(preview){const open=!preview&&S.rfq.status==='sent'&&!S.rfq.quotes.ganesh;
  return `<div class="bub"><div class="from">${esc(FACTORY.name)}</div>Request for quotation <b>${RFQ.no}</b><dl><dt>Part</dt><dd>${esc(SHORT.name)}, 6 in</dd><dt>Quantity</dt><dd>${NEED_QTY} nos</dd><dt>Needed by</dt><dd>${dmyy(RFQ.need)}</dd><dt>Reply by</dt><dd>${dmyy(RFQ.replyBy)}</dd><dt>Drawing</dt><dd>Rev A · on the link</dd></dl>Machining allowance 3 mm all over. Our pattern.
  <div style="margin-top:6px;padding-top:6px;border-top:1px dashed var(--line-2);font-size:12px"><b>How we check it on arrival</b> (${QPLAN.sample})<ul>${QPLAN.checks.map(c=>`<li>${esc(c[0])}: ${esc(c[1])}</li>`).join('')}</ul></div>
  ${preview?`<span class="go dim">${I('link')}Quote in one minute</span>`:open?`<button class="go" data-go="s.quote">${I('link')}Quote in one minute</button>`:`<span class="go dim">${S.rfq.quotes.ganesh?'Quoted · tap Quote to change it':'Request closed'}</span>`}
  <div class="t">${preview?'preview':tm(S.supMsgs[0]?S.supMsgs[0].at:S.clock)}</div></div>`}
function ansRow(r){const s=r.s,awarded=S.po&&S.po.sup===r.id;let act='';
  if(S.rfq.status==='sent'){if(r.late)act=`<div class="aact"><button class="btn gh sm" disabled>Award</button><small style="color:var(--red)">Misses ${dmy(RFQ.need)}</small></div>`;
    else if(!s.vendor)act=`<div class="aact"><button class="btn gh sm" data-a="award" data-id="${r.id}">Award</button>${S.invited[r.id]?tp('Invited to claim its record','info'):`<button class="btn gh sm" data-a="invite" data-id="${r.id}">${I('link')}Invite to claim its record</button>`}<small style="color:var(--ochre)">Not an approved vendor yet · a trial order starts its record</small></div>`;
    else act=`<div class="aact"><button class="btn ${r.rank===1?'pri':'gh'} sm" data-a="award" data-id="${r.id}">${I('award')}Award</button><small>${r.rank===1?'Top of the ranking':'Allowed, but not the top answer'}</small></div>`}
  else if(awarded)act=`<div class="aact">${tp('Awarded · '+S.po.no,'ok')}</div>`;
  const lead=r.late?`Promised ${dmy(r.date)}, after the need date, so it can’t be used however cheap.`:r.date?`Promised ${dmy(r.date)}, ${days(r.date,RFQ.need)} day${days(r.date,RFQ.need)===1?'':'s'} before it’s needed.`:'No delivery date given, so it scores nothing for delivery.';
  const o=onTimePct(r.id);
  const proof=o==null?`<div class="proof unk">${I('alert')}<span><b style="color:inherit">Unproven.</b> Never delivered to Kaveri, so its promise is taken on trust and its record scores 0.</span></div>`
    :`<div class="proof"><span>Record: <b>${Math.round(o)}%</b> of ${H(r.id).deliveries} deliveries on time · <b>${rejPct(r.id).toFixed(1)}%</b> rejected → expect about <b>${r.expRej.toFixed(1)}</b> of ${NEED_QTY} to fail inspection</span><span>${s.xelor?`Capacity: <b>${esc(s.xelor.free)}</b>, read live from their XELOR`:'Capacity: as stated in the reply'}</span></div>`;
  const m=(k,v,w,c)=>`<div><div class="mk">${k}</div><div class="mv">${v}</div>${w!=null?`<div class="bar-s"><i style="width:${Math.round(w*100)}%;background:${c}"></i></div>`:''}</div>`;
  return `<div class="ans ${r.late?'late':''} ${awarded?'won':''}" data-flip="${r.id}"><span class="rank ${r.rank===1?'first':''}">${r.late?'✕':r.rank}</span><div class="b">
    <h4>${esc(s.name)}${s.xelor?vbadge():''}${s.vendor?'':tp('Network only','warn')}${r.fresh&&r.id==='ganesh'?tp('Just quoted','acc'):''}${r.id==='anand'?tp('Agent reply · API','info'):r.id==='veera'?tp('Simulated reply'):''}</h4>
    <p class="why">${esc(lead+' '+(r.note||''))}</p>${proof}
    <div class="mets">${m('Landed',inr(r.landed))}${m('Per piece',inr2(r.unit))}${m('Delivery',r.speed.toFixed(2),r.speed,'var(--acc)')}${m('Price',r.cost.toFixed(2),r.cost,'var(--blue)')}${m('Record',r.rec.toFixed(2),r.rec,'var(--gold)')}${m('Score',r.late?'—':r.score.toFixed(2))}</div>${act}</div></div>`}
def('p.net',{role:'pur',title:'Supplier network',route:'/purchase/network/rfqs/RFQ-2627-0114',purpose:'Ask foundries for a price and get the answers back ranked. The request is written from records XELOR holds; each supplier shows its earned record and, when it runs XELOR, live capacity. Ranking weighs delivery, landed cost and track record, and explains itself.',
  reads:['Item master, BOM, quality plan QP-BDY-150','Vendor approval status','Supplier performance from Kaveri’s receipts and inspections','Live capacity (suppliers on XELOR)'],
  api:[['Create RFQ','POST /api/v1/purchase/rfqs'],['Issue + broadcast','POST /api/v1/purchase/network/rfqs/{id}/broadcast'],['Performance','GET /api/v1/purchase/network/suppliers/{id}/performance'],['Ranking','GET /api/v1/purchase/network/rfqs/{id}/ranking'],['Award → PO','POST /api/v1/purchase/rfqs/{id}/award']],
  states:['nothing short','choose who to ask','waiting for replies','ranked','late answer (unusable)','award refused (not a vendor)','awarded'],
  rules:['Anyone on the network can quote; only an approved vendor can be awarded','An answer after the need date is unusable however cheap','Track record is counted, never typed; no record scores 0 and says unproven','Messages are composed, not delivered, in this demo'],
  render(){
    if(!S.planRun)return head('Supplier network','Every foundry this factory can ask for a price, and what each one has actually delivered.')+waitFor(1,'Nothing to ask for yet');
    if(S.rfq.status==='none'){const n=SUP_ORDER.filter(id=>ui.pick[id]).length;
      return `${head('Ask for a price','XELOR wrote the request from records it already holds. Choose who to ask. They answer from a link with no login.')}
      <div class="two"><div class="card"><h4>Who to ask</h4><p class="sub">Suppliers who pour grey iron castings</p><div class="list">${SUP_ORDER.map(id=>{const s=SUP[id];return `<div class="sup ${ui.pick[id]?'on':''}" role="checkbox" tabindex="0" aria-checked="${!!ui.pick[id]}" data-a="pick" data-id="${id}"><span class="cbx">${I('check')}</span>${logo(id)}<span class="tx"><b>${esc(s.name)}${s.xelor?vbadge():''}</b><small>${esc(s.town)} · ${s.km} km · replies in about ${s.reply}</small><span class="stats">${recLine(id)}</span>${capLine(id)}</span>${s.vendor?tp('Approved','ok'):tp('Network only','warn')}</div>`}).join('')}</div>
        <button class="btn pri block" data-a="sendRfq" ${n?'':'disabled'}>${I('send')}Send request to ${n} supplier${n===1?'':'s'}</button></div>
      <div style="display:flex;flex-direction:column;gap:12px;min-width:0">${packCard()}${card('What each supplier receives','A message with a private link, and the same request for supplier software',`<div class="thread" style="margin:0;border-radius:12px;min-height:0">${rfqBubble(true)}</div><details class="json"><summary>${I('link')} Machine-readable request · for supplier order-desk agents</summary><pre>${esc(JSON.stringify({rfq:RFQ.no,item:SHORT.code,qty:NEED_QTY,need_by:RFQ.need,reply_by:RFQ.replyBy,deliver_to:'Peenya, Bengaluru 560058',quality_plan:QPLAN.no,quote_url:'https://kaveri.xelor.in/q/…'},null,1))}</pre></details>`)}</div></div>`}
    const rows=ranked(),miss=S.rfq.to.filter(id=>!S.rfq.quotes[id]),usable=rows.filter(r=>!r.late);
    return `${head('Answers for '+RFQ.no,`${NEED_QTY} × ${esc(SHORT.name)} · needed by ${dmyy(RFQ.need)} · ranked on delivery, landed cost and each supplier’s real record.`)}
    <div class="kpis"><div class="kpi hl"><b>${rows.length} of ${S.rfq.to.length}</b><span>${miss.length?'answers in · reply by '+dmy(RFQ.replyBy):'everyone answered'}</span></div><div class="kpi"><b>${usable.length?inr(Math.min(...usable.map(r=>r.landed))):'—'}</b><span>best landed cost, before GST</span></div><div class="kpi"><b>${usable.length>1?inr(Math.max(...usable.map(r=>r.landed))-Math.min(...usable.map(r=>r.landed))):'—'}</b><span>spread, best to worst</span></div><div class="kpi"><b>${rows.filter(r=>onTimePct(r.id)!=null).length} of ${rows.length}</b><span>answers backed by deliveries</span></div></div>
    
    <div class="card"><div class="row sb"><h4>Ranked answers</h4><span class="sub">The ranking explains; you decide</span></div>
      <div class="weights"><i style="flex:${W.speed};background:var(--acc)"></i><i style="flex:${W.cost};background:var(--blue);animation-delay:.08s"></i><i style="flex:${W.rec};background:var(--gold);animation-delay:.16s"></i></div>
      <div class="weights-k"><span style="--c:var(--acc)">Delivery promised 40%</span><span style="--c:var(--blue)">Landed cost 35%</span><span style="--c:var(--gold)">Track record 25%</span></div></div>
    <div class="list">${rows.map(ansRow).join('')}${miss.map(id=>`<div class="ans wait" data-flip="${id}"><span class="rank">·</span><div class="b"><h4>${esc(SUP[id].name)}</h4><p class="why">${SUP[id].live?`Answering on the phone. <button class="linkbtn" data-go="s.quote">Open Sri Ganesh’s phone</button> to send the quote.`:`Waiting for a reply <span class="tdots"><i></i><i></i><i></i></span>`}</p></div></div>`).join('')}</div>`}});

def('p.po',{role:'pur',title:'Purchase orders',route:'/purchase/orders/PO-2627-00415',purpose:'The purchase order raised straight from the award, checked against Priya’s approval limit. Above it, the order goes to the owner’s phone; the person who awards never approves.',
  reads:['Award + ranked answer','Approval limits by person','Supplier Udyam status'],api:[['PO','GET /api/v1/purchase/orders/{id}'],['Submit for approval','POST /api/v1/purchase/orders/{id}/submit'],['Approve (owner)','POST /api/v1/purchase/orders/{id}/approve'],['History','GET /api/v1/purchase/orders/{id}/history']],
  states:['no PO yet','awaiting approval','approved and sent','sent back'],rules:['Limit is a rule, not a warning: Priya can’t approve above ₹1,50,000','Maker–checker: the awarder never approves','Every state change is in the order’s history'],
  render(){if(!S.po)return head('Purchase orders','Raised from an award, checked against the buyer’s limit.')+waitFor(3,'No purchase order yet');const p=S.po,s=SUP[p.sup],ap=p.status==='approved';
    const steps=[['Raised by Priya from the award',stamp(p.raised),'done'],[p.needsOwner?`Above Priya’s ${inr(PEOPLE.priya.limit)} limit, so it goes to Arun`:'Within Priya’s limit',p.needsOwner?'The person who awards never approves':'No second signature needed','done'],
      [ap?'Approved by '+p.approvedBy:'Waiting on Arun Venkatesh, owner',ap?stamp(S.stamped[4]):'On his phone now',ap?'done':'now'],['Sent to '+s.short,ap?`Deliver ${NEED_QTY} by ${dmy(p.promised)}`:'After approval',ap?'done':'']];
    return `${head('Purchase order '+p.no,ap?'Approved and with the supplier. Stores will receive against it.':'Raised straight from the award. Nothing was retyped.')}
    <div class="two"><div class="docsheet"><div class="dh"><div><h4>Purchase order</h4><div class="no">${p.no} · from ${RFQ.no}</div></div>${ap?stampHtml('Approved',S.stamped[4],false,true,S.justStamped===4):tp('Awaiting approval','warn')}</div>
      <div class="parties"><div><small>Supplier</small><b>${esc(s.name)}</b><br>${esc(s.town)}<br>Udyam: ${s.msme} enterprise</div><div><small>Deliver to</small><b>${esc(FACTORY.name)}</b><br>${FACTORY.town}<br>by ${dmyy(p.promised)}</div></div>
      <div class="scx"><table class="tbl"><thead><tr><th>Item</th><th class="r">Qty</th><th class="r">Rate</th><th class="r">Amount</th></tr></thead><tbody>
      <tr><td><b>${esc(SHORT.name)}</b><div class="s mono">${SHORT.code}</div></td><td class="r num">${NEED_QTY}</td><td class="r num">${inr2(p.unit)}</td><td class="r num">${inr(p.unit*NEED_QTY)}</td></tr>
      ${p.freight?`<tr><td>Freight to Peenya</td><td></td><td></td><td class="r num">${inr(p.freight)}</td></tr>`:''}
      <tr><td colspan="3" class="r s">IGST 18% · ${p.sup==='veera'?'Karnataka, intra-state':'Tamil Nadu to Karnataka'}</td><td class="r num">${inr(p.gst)}</td></tr>
      <tr class="tot"><td colspan="3" class="r">Total</td><td class="r num">${inr(p.total)}</td></tr></tbody></table></div></div>
    <div class="card"><h4>Approval</h4>${pipeHtml(steps)}${p.status==='awaiting'?`<button class="btn pri block" data-go="w.po">${I('phone')}Open Arun’s phone</button><p class="note center">Priya can’t approve it herself. The limit is a rule, not a warning.</p>`:''}</div></div>`}});

function scorecard(){return `<div class="scx"><table class="tbl"><thead><tr><th>Supplier</th><th class="r">Deliveries</th><th class="r">On time</th><th class="r">Pieces checked</th><th class="r">Rejected</th><th>Record</th><th>Status</th></tr></thead><tbody>
  ${SUP_ORDER.map(id=>{const s=SUP[id],h=H(id),base=s.hist,o=onTimePct(id),rj=rejPct(id),rs=recScore(id);const dD=h&&base?h.deliveries-base.deliveries:h?h.deliveries:0,dP=h&&base?h.pieces-base.pieces:h?h.pieces:0;
  return `<tr class="${S.bumped===id?'bump':''}"><td><div class="row">${logo(id)}<div><b style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">${esc(s.short)}${s.xelor?vbadge():''}</b><div class="s">${h?'since '+h.since:'never delivered to Kaveri'}</div></div></div></td>
  <td class="r num">${h?h.deliveries:0}${dD?`<span class="delta">+${dD}</span>`:''}</td><td class="r num">${o==null?'—':Math.round(o)+'%'}</td><td class="r num">${h?nos(h.pieces):0}${dP?`<span class="delta">+${dP}</span>`:''}</td><td class="r num">${rj==null?'—':rj.toFixed(1)+'%'}</td>
  <td>${o==null?tp('Unproven','warn'):`<div class="bar-s" style="width:80px"><i style="width:${Math.round(rs*100)}%;background:var(--gold)"></i></div><div class="s mono">${rs.toFixed(2)}</div>`}</td><td>${s.vendor?tp('Approved','ok'):tp('Network only','warn')}</td></tr>`}).join('')}</tbody></table></div>`}
def('p.rec',{role:'pur',title:'Supplier records',route:'/purchase/network/suppliers',purpose:'Every supplier’s record, earned not claimed: deliveries, on-time share, pieces checked and rejected, counted from Kaveri’s own receipts and inspections. Beside it, Kaveri’s own record as a buyer would see it.',
  reads:['Goods receipts by supplier','Incoming inspection results','Kaveri’s on-time shipments'],api:[['Performance','GET /api/v1/purchase/network/suppliers/{id}/performance'],['Suppliers','GET /api/v1/purchase/network/suppliers']],
  states:['proven','unproven (no deliveries)','updated by a receipt','updated by an inspection'],rules:['No number on this screen is typed by a person','A receipt counts on-time; an inspection counts pieces and rejects','Proposed: offering spare capacity publishes nothing in this demo'],
  render(){const n=KAVERI_REC.orders+(S.closed?1:0),ok=KAVERI_REC.onTimeN+(S.closed&&S.dispatch.at.slice(0,10)<=ORDER.due?1:0);
    return `${head('Supplier records','Earned, not claimed. Every number comes from a receipt or an inspection at Kaveri’s gate.')}${scorecard()}`}});

def('p.log',{role:'pur',title:'Activity',route:'/activity?order=SO-2627-0291',purpose:'Everything that happened to this order, newest first, with who did it. Nothing here can be edited; a mistake is corrected by a new entry.',
  reads:['Audit log for the order'],api:[['Audit pack','GET /api/v1/admin/audit/pack?ref=SO-2627-0291']],states:['empty','entries'],rules:['Append-only','Each entry names a person or a system'],
  render(){return `${head('Activity','Everything that happened to this order, newest first. Nothing here can be edited.')}
    ${S.log.length?`<div class="card">${S.log.map(l=>`<div class="fact"><span class="fi">${I(/XELOR/.test(l.who)?'spark':/Ganesh Castings|Anand|Veera/.test(l.who)?'msg':'users')}</span><div><div class="fn">${esc(l.what)}</div><div class="fs">${esc(l.who)} · ${esc(l.detail)}</div></div><span class="sub mono" style="font-size:10.5px;text-align:right">${dmy(l.at.slice(0,10))}<br>${tm(l.at)}</span></div>`).join('')}</div>`:empty('list','Nothing has happened yet','Confirm the order and every step after it is recorded here.',`<button class="btn pri sm" data-go="p.sales">Open the order${I('arrow')}</button>`)}`}});

/* ================= SUPPLIER (Sri Ganesh, phone) ================= */
def('s.chat',{role:'sup',title:'Kaveri Pumps',kn:'via XELOR · business account',route:'/messages · business thread (preview)',purpose:'What the foundry actually receives: a message from Kaveri’s business number carrying the request and a private link. Award, PO, receipt and payment-due notes arrive in the same thread.',
  reads:['Outbound messages for this supplier'],api:[['Outbox','GET /api/v1/purchase/network/outbox'],['Broadcasts','GET /api/v1/purchase/network/broadcasts']],
  states:['no request yet','request with link','quote sent','won / not chosen / withdrawn','PO confirmed','received + payment due'],rules:['Delivery defaults to preview: composed, not sent, until a provider is connected','The supplier never sees other quotes or the ranking'],
  render(){const p=S.po;const msgs=S.supMsgs.map(m=>{switch(m.kind){
      case 'rfq':return rfqBubble(false);
      case 'sent':return `<div class="bub me">Quote sent: <b>${inr2(m.unit)}</b> per piece${m.date?', delivery '+dmy(m.date):''}. Landed total ${inr(m.landed)}.<div class="t">${tm(m.at)} ✓✓</div></div>`;
      case 'won':return `<div class="bub"><div class="from">${esc(FACTORY.name)}</div>You’ve been selected for ${RFQ.no}. Purchase order ${p?p.no:''} is raised and waiting on Kaveri’s approval.<div class="t">${tm(m.at)}</div></div>`;
      case 'lost':return `<div class="bub"><div class="from">${esc(FACTORY.name)}</div>Kaveri chose another supplier for ${RFQ.no} this time. Your quote stays on file.<div class="t">${tm(m.at)}</div></div>`;
      case 'pulled':return `<div class="bub"><div class="from">${esc(FACTORY.name)}</div>The award on ${RFQ.no} has been withdrawn while Kaveri reviews it.<div class="t">${tm(m.at)}</div></div>`;
      case 'po':return `<div class="bub"><div class="from">${esc(FACTORY.name)}</div><b>${p?p.no:''} is confirmed.</b> Please deliver ${NEED_QTY} castings to Peenya by ${p?dmyy(p.promised):''}. Reply OK to acknowledge.<div class="t">${tm(m.at)}</div></div><div class="bub me">OK. Pouring starts tomorrow on Furnace 2.<div class="t">${tm(m.at)} ✓✓</div></div>`;
      case 'treds':return `<div class="bub"><div class="from">${esc(FACTORY.name)}</div>Your invoice for ${inr(p?p.total:0)} is on TReDS. You can take early payment now, or wait for ${p?dmyy(addDays(p.promised,45)):''}.<div class="t">${tm(m.at)}</div></div>`;
      case 'received':return `<div class="bub"><div class="from">${esc(FACTORY.name)}</div>Received ${NEED_QTY} on time. Inspection passed, 0 rejected. Payment is due by ${p?dmyy(addDays(p.promised,45)):''} under the 45 days agreed on the PO.<div class="t">${tm(m.at)}</div></div>`}return ''}).join('');
    return `<div class="thread"><div class="sysnote">${I('lock')} In this demo messages are composed, not sent. No messaging provider is connected.</div>${msgs||`<div class="sysnote" style="margin-top:30px">No requests yet. When Kaveri asks for a price it arrives here as a message with a link.</div>`}
      ${S.rfq.status==='sent'&&S.rfq.quotes.ganesh?`<button class="btn gh sm" data-go="s.quote" style="align-self:flex-end">${I('rupee')}Change my price</button>`:''}</div>`}});
def('s.quote',{role:'sup',title:'Your price',kn:'kaveri.xelor.in/q · no login',route:'/q/:token',nav:'s.quote',purpose:'The no-login quote page behind the link. One required field, price per piece; delivery date and freight are optional. The foundry sees the need date, the inspection plan and its own record before it prices.',
  reads:['RFQ by signed token','The supplier’s own record with Kaveri'],api:[['Open link','GET /api/v1/supplier/{token}'],['Submit quote','POST /api/v1/supplier/{token}/quote']],
  states:['no open request','empty','typing (live total)','late date warning','sent','request closed'],rules:['Price per piece is the only required field','A date after the need date can be sent but can’t be used','The link expires when the request closes'],
  cta:()=>S.rfq.status==='sent'&&S.rfq.to.includes('ganesh')?`<button class="im-btn out big" data-nav="s.chat">Cancel</button><button class="im-btn pri big" id="qSend" data-a="send-quote" ${Number(String(S.draft.unit).replace(/,/g,''))>0?'':'disabled'} style="flex:2;background:var(--role);color:var(--on-role)">${I('send')}Send quote</button>`:`<button class="im-btn out big" data-nav="s.chat">Back to chats</button>`,
  render(){if(S.rfq.status==='none'||!S.rfq.to.includes('ganesh'))return empty('rupee','No open request','When Kaveri asks for a price, the link in the message opens this page. No account, no password.');
    if(S.rfq.status!=='sent')return empty('lock','This request is closed',S.po&&S.po.sup==='ganesh'?'You won it. The purchase order is in your chats.':'Kaveri has awarded it. Your quote stays on file.',`<button class="btn pri sm" data-nav="s.chat">Open chats</button>`);
    if(!S.draft.unit&&S.rfq.quotes.ganesh){const q=S.rfq.quotes.ganesh;S.draft={unit:String(q.unit),date:q.date||'',freight:q.freight?String(q.freight):'',note:''}}
    const d=S.draft,unit=Number(String(d.unit).replace(/,/g,''))||0,fr=Number(String(d.freight).replace(/,/g,''))||0,late=d.date&&d.date>RFQ.need;
    return `<div class="card tint"><span class="eyb">They are asking for</span><h4>${NEED_QTY} × ${esc(SHORT.name)}</h4>${kv('Needed by',dmyy(RFQ.need))}${kv('Reply by',dmyy(RFQ.replyBy))}${kv('Deliver to','Peenya, Bengaluru')}${kv('Checked on arrival',QPLAN.checks.length+' checks · '+QPLAN.sample)}</div>
    <div class="vn"><button class="vnb" data-a="voice" aria-label="Reply by voice note">${I('mic')}</button><div class="grow"><b>${S.voice?'Voice note · 0:07':'Reply by voice note'}</b><span>${S.voice?'“Ondu piece-ge ₹2,760, October 9-kke delivery, freight ₹2,400.” → filled below':'Kannada, Tamil, Hindi or English. XELOR fills the form.'}</span></div>${S.voice?'<span class="wave play"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span>':''}</div>${S.voice?'<p class="note">Transcribed in this demo. No speech model is connected.</p>':''}
    <label class="fl" for="qUnit">Price per piece <span class="kn">the only required field</span></label><div class="money"><span>₹</span><input id="qUnit" inputmode="decimal" placeholder="0" value="${esc(d.unit)}" autocomplete="off"></div>
    <div class="row sb"><span class="sub">Excluding GST</span><button class="linkbtn" data-a="fill">Fill ₹2,760 · 9 Oct · ₹2,400 freight</button></div>
    <label class="fl" for="qDate">Delivery date <span class="kn">optional</span></label><input id="qDate" class="field" type="date" value="${esc(d.date)}"><p class="note" id="qLate" style="${late?'color:var(--red)':''}">${late?`After ${dmy(RFQ.need)}. You can still send it, but it can’t be used.`:'Leave it blank if unsure. A blank date beats a missed one.'}</p>
    <label class="fl" for="qFreight">Freight to Peenya <span class="kn">optional</span></label><div class="money"><span>₹</span><input id="qFreight" inputmode="decimal" placeholder="0" value="${esc(d.freight)}" autocomplete="off"></div>
    <div class="qtotal"><div><small>What they will compare</small><span style="color:var(--on-deep);font-size:13px">${NEED_QTY} pieces + freight</span></div><b id="qTotal">${unit?inr(unit*NEED_QTY+fr):'—'}</b></div>`}});
def('s.record',{role:'sup',title:'My record',kn:'with Kaveri Pumps',route:'/q/:token/record',purpose:'The foundry’s own record with Kaveri, as Kaveri counts it at the gate. It shows the supplier exactly what feeds a quarter of the ranking, so keeping promises now wins work later.',
  reads:['Receipts and inspections for this supplier at Kaveri'],api:[['Performance (own)','GET /api/v1/purchase/network/suppliers/{id}/performance']],states:['proven','updated today'],rules:['The supplier sees its own record, never anyone else’s','Counted from receipts and inspections; never typed'],
  render(){const h=H('ganesh'),o=onTimePct('ganesh'),rj=rejPct('ganesh'),rs=recScore('ganesh'),b=SUP.ganesh.hist;const C=2*Math.PI*26;
    return `<div class="hero"><span class="eyb">Sri Ganesh Castings · since ${h.since}</span><h4>${Math.round(o)}% on time over ${h.deliveries} deliveries</h4><p>${rj.toFixed(2)}% of ${nos(h.pieces)} pieces rejected at Kaveri’s gate. Record score ${rs.toFixed(2)} of 1.</p></div>
    <div class="kpis" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="kpi hl"><b>${h.deliveries}${h.deliveries>b.deliveries?`<span class="delta">+${h.deliveries-b.deliveries}</span>`:''}</b><span>deliveries</span></div><div class="kpi"><b>${h.onTimeN}</b><span>on time</span></div><div class="kpi"><b>${nos(h.pieces)}${h.pieces>b.pieces?`<span class="delta">+${h.pieces-b.pieces}</span>`:''}</b><span>pieces checked</span></div><div class="kpi"><b>${h.rejected}</b><span>rejected</span></div></div>
    <div class="card"><div class="row"><svg class="ring" viewBox="0 0 64 64" aria-label="Record ${rs.toFixed(2)}"><circle class="bg" cx="32" cy="32" r="26"/><circle class="fg" cx="32" cy="32" r="26" stroke-dasharray="${C}" stroke-dashoffset="${C*(1-rs)}"/><text x="32" y="37" text-anchor="middle">${Math.round(rs*100)}</text></svg><div class="grow"><h4>How Kaveri scores your record</h4><p class="sub">On-time share counts 70%. Rejects count 30%: 0% is full marks, 5% or worse is nothing.</p></div></div></div>`}});
def('s.cap',{role:'sup',title:'Furnace 2',kn:'live capacity · runs XELOR',route:'/capacity · Sri Ganesh’s own XELOR',purpose:'Sri Ganesh runs XELOR in its own foundry, so its free capacity is read from its schedule and shown to buyers who ask it for a price. A promise backed by a schedule is believable.',
  reads:['Own furnace schedule (Sri Ganesh’s XELOR)'],api:[['Capacity (shared)','GET /api/v1/planning/mrp/runs/{runNo}/capacity']],states:['free capacity','fully booked','shared with a buyer'],rules:['Shared only with buyers who send this supplier a request','Read from the schedule; never typed into a profile'],
  render(){const x=SUP.ganesh.xelor;const won=S.po&&S.po.sup==='ganesh'&&S.po.status==='approved';const booked=won?84:x.booked;const C=2*Math.PI*26;
    const daysL=['1 Oct','2','3','4','5','6','7','8','9 Oct','10'];const load=[90,70,40,55,30,95,60,45,35,80].map((v,i)=>won&&i>=1&&i<=4?Math.min(100,v+40):v);
    return `<div class="card"><div class="row"><svg class="ring" viewBox="0 0 64 64" aria-label="${booked}% booked"><circle class="bg" cx="32" cy="32" r="26"/><circle class="fg" cx="32" cy="32" r="26" stroke-dasharray="${C}" stroke-dashoffset="${C*(1-booked/100)}"/><text x="32" y="37" text-anchor="middle">${booked}%</text></svg><div class="grow"><h4>${esc(x.line)} · ${booked}% booked</h4><p class="sub">${won?'Kaveri’s 60 bodies are scheduled · 1 pour free before 9 Oct':esc(x.free)}</p>${vbadge()}</div></div></div>
    <div class="card"><h4>Next ten days</h4><div class="bars">${daysL.map((d,i)=>`<div class="bar" style="grid-template-columns:52px minmax(0,1fr) 40px"><span>${d}</span><span class="tr"><i style="width:${load[i]}%;background:${load[i]>85?'var(--red)':'var(--role)'};animation-delay:${i*40}ms"></i></span><b>${load[i]}%</b></div>`).join('')}</div></div>`}});

/* ================= OWNER (Arun, phone) ================= */
def('w.inbox',{role:'own',title:'Needs you',kn:'Arun Venkatesh · Owner',route:'/inbox',purpose:'Only what needs the owner: approvals above someone’s limit. Everything else is visible but never asks for him.',
  reads:['Workflow tasks assigned to the owner'],api:[['Inbox','GET /api/v1/workflow/inbox?assignee=me']],states:['nothing waiting','approval waiting','approved today'],rules:['Approvals come here only when above someone’s limit','A tap opens the full reasoning before signing'],
  render(){const p=S.po,n=nextStep();return `<div class="hero"><span class="eyb">Kaveri Pumps · ${new Date(S.clock).toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'short'})}</span><h4>${p&&p.status==='awaiting'?'One approval needs you.':'Nothing needs you right now.'}</h4><p>${p&&p.status==='awaiting'?'Above Priya’s limit, so it came to you.':'Approvals arrive here only when they’re above someone’s limit.'}</p></div>
    ${p&&p.status==='awaiting'?`<div class="card gold"><div class="eyb" style="color:var(--gold-ink)">Purchase order · needs you</div><div class="act" data-go="w.po" role="button" tabindex="0">${logo(p.sup)}<div class="grow"><b style="color:var(--ink);font-size:14px">${esc(SUP[p.sup].name)}</b><div class="sub">${p.no} · ${NEED_QTY} pump bodies</div></div><b class="big" style="font-size:17px">${inr(p.exGst)}</b>${I('right')}</div></div>`:''}
    ${p&&p.status==='approved'&&p.approvedBy==='Arun Venkatesh'?`<div class="card ok"><div class="row sb"><b style="color:var(--ink)">You approved ${p.no}</b>${pill('approved')}</div><p class="sub">${inr(p.exGst)} to ${esc(SUP[p.sup].short)} · supplier told on the same tap</p></div>`:''}
    <div class="card"><div class="row sb"><h4>The order today</h4><span class="badge">${Object.keys(S.stamped).length}/9</span></div><div class="levels" style="grid-template-columns:repeat(9,1fr)">${STAGES.map((s,i)=>`<span class="lv ${stageDone(i)?'on':''}" title="${esc(s.name)}">${i+1}</span>`).join('')}</div><p class="note">${n.done?'Closed. Typed once, carried through nine stations.':'Next: '+esc(n.t.toLowerCase())+'.'}</p></div>`}});
def('w.po',{role:'own',title:'Approve',kn:'PO-2627-00415',route:'/inbox/po/:id',nav:'w.inbox',purpose:'One purchase order with the reasons it reached the owner, the ranking it came from and the supplier’s earned record. Approve or send back with one tap; the supplier and Priya see the result at once.',
  reads:['PO + award + ranking','Supplier record','Approval rule that routed it'],api:[['PO','GET /api/v1/purchase/orders/{id}'],['Approve','POST /api/v1/purchase/orders/{id}/approve'],['Send back','POST /api/v1/purchase/orders/{id}/reject']],
  states:['awaiting','approved','sent back','nothing to approve'],rules:['Only the owner can approve above ₹1,50,000','Sending back undoes the award; the answers stay ranked'],
  cta:()=>S.po&&S.po.status==='awaiting'?`<button class="im-btn out big" data-a="send-back">Send back</button><button class="im-btn pri big" data-a="approve" style="flex:2;background:var(--green);color:var(--on-green)">${I('check')}Approve</button>`:`<button class="im-btn out big" data-back>Back</button>`,
  render(){const p=S.po;if(!p)return empty('inbox','Nothing to approve','A purchase order lands here when it’s above someone’s limit.');const s=SUP[p.sup],o=onTimePct(p.sup);
    return `<div class="card ${p.status==='awaiting'?'gold':'ok'}"><div class="row sb"><span class="eyb" style="color:var(--gold-ink)">Purchase order</span>${p.status==='awaiting'?pill('pending'):pill('approved')}</div><div class="row">${logo(p.sup)}<div class="grow"><h4>${esc(s.name)}</h4><p class="sub">${esc(s.town)} · Udyam ${s.msme}</p></div></div><div class="amt">${cu(p.exGst,'inr')}</div><p class="sub">${NEED_QTY} × ${esc(SHORT.name)} · before GST · deliver ${dmy(p.promised)}</p></div>
    <div class="card"><h4>Why it’s with you</h4><p class="sub">${inr(p.exGst)} is above Priya’s ${inr(PEOPLE.priya.limit)} limit, and the person who awards never approves.</p></div>
    <div class="card"><h4>What it was decided from</h4>${kv('Ranked',p.rank+' of '+ranked().filter(r=>!r.late).length+' usable answers')}${kv('Delivery',dmy(p.promised)+' · '+days(p.promised,RFQ.need)+' days before need')}${kv('Record',o!=null?Math.round(o)+'% on time · '+rejPct(p.sup).toFixed(1)+'% rejected':'unproven')}${kv('For order',ORDER.no+' · '+inr(INVOICE_TOTAL))}</div>
    ${p.status==='approved'?`<div class="tick">${I('check')}</div><p class="center sub">Approved by ${esc(p.approvedBy)} · ${stamp(S.stamped[4])}</p>`:''}`}});
def('w.today',{role:'own',title:'Today at Kaveri',kn:'what happened, as it happened',route:'/today',purpose:'A quiet feed of the moments that matter to an owner: orders confirmed, shortages, answers in, approvals, receipts, dispatch. Read, not acted on.',
  reads:['Owner-level events'],api:[['Feed','GET /api/v1/workflow/feed?scope=owner']],states:['quiet','events'],rules:['The feed informs; only approvals ask for action'],
  render(){S.unread.own=0;return S.ownerFeed.length?`<div class="card">${S.ownerFeed.map((f,i)=>`<div class="feedline ${i===0?'new':''}"><span class="d"></span><div><b>${esc(f.text)}</b><small>${esc(f.sub)} · ${stamp(f.at)}</small></div></div>`).join('')}</div>`:empty('list','Quiet so far','Orders, shortages and answers show up here as they happen.')}});
def('w.biz',{role:'own',title:'Business',kn:'one order, in money',route:'/business',purpose:'What this one order means in money and time: value, what the customer will owe, what Kaveri will owe the foundry and by when, and how far along it is.',
  reads:['Order, PO, receivable, payable'],api:[['Trial balance','GET /api/v1/accounts/trial-balance'],['Outstanding','GET /api/v1/accounts/customers/{id}/outstanding']],states:['before dispatch','after dispatch','closed'],rules:['MSME suppliers must be paid within 45 days of acceptance (section 43B(h))','Synthetic demo figures; never claimed as savings'],
  render(){const n=Object.keys(S.stamped).length,C=2*Math.PI*26;const pay=S.grn&&!S.grn.pending?addDays(S.po.promised,45):null;
    return `<div class="card"><div class="row"><svg class="ring" viewBox="0 0 64 64" aria-label="${n} of 9 stations"><circle class="bg" cx="32" cy="32" r="26"/><circle class="fg" cx="32" cy="32" r="26" stroke-dasharray="${C}" stroke-dashoffset="${C*(1-n/9)}"/><text x="32" y="37" text-anchor="middle">${n}/9</text></svg><div class="grow"><h4>${ORDER.no}</h4><p class="sub">${ORDER.qty} pumps for ${esc(CUSTOMER.name)} · due ${dmy(ORDER.due)}</p></div></div></div>
    <div class="kpis" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="kpi hl"><b>${cu(INVOICE_TOTAL,'inr')}</b><span>order value</span></div><div class="kpi"><b>${S.dispatch&&!S.dispatch.running?inr(INVOICE_TOTAL):'—'}</b><span>${S.dispatch&&!S.dispatch.running?'customer owes · due '+dmy(addDays(S.dispatch.at.slice(0,10),30)):'receivable after dispatch'}</span></div><div class="kpi"><b>${S.po?inr(S.po.total):'—'}</b><span>owed to the foundry</span></div><div class="kpi"><b>${pay?dmy(pay):'—'}</b><span>${pay?'MSME pay-by date':'clock starts at receipt'}</span></div></div>`}});

/* ================= STORES & QUALITY (tablet) ================= */
function recordDelta(id){const b=SUP[id].hist,h=H(id),s=SUP[id];const bo=b?b.onTimeN/b.deliveries*100:null,br=b?b.rejected/b.pieces*100:null;
  const line=(k,f,t)=>`<tr><td class="s">${k}</td><td class="r num" style="color:var(--muted)">${f}</td><td style="width:22px;text-align:center;color:var(--muted)">→</td><td class="r num"><b style="color:var(--green-ink)">${t}</b></td></tr>`;
  return card(esc(s.short)+'’s record, updated','By this receipt'+(S.inspection==='pass'?' and inspection':'')+', not by anyone typing',`<div class="scx"><table class="tbl"><tbody>${line('Deliveries',b?b.deliveries:0,h.deliveries)}${line('On time',bo==null?'—':Math.round(bo)+'%',Math.round(onTimePct(id))+'%')}${line('Pieces checked',b?nos(b.pieces):0,nos(h.pieces))}${line('Rejected',br==null?'—':br.toFixed(2)+'%',h.pieces?rejPct(id).toFixed(2)+'%':'—')}</tbody></table></div><p class="note">${S.inspection==='pass'?'Next time Kaveri asks for castings, this record feeds the ranking.':'Pieces and rejects update when quality decides on the lot.'}</p>`)}
def('t.gate',{role:'stores',title:'Gate',route:'/stores/receipts',purpose:'Receiving against an approved PO. One scan of the challan posts the goods receipt: stock up (held for inspection), valuation, and the supplier’s on-time record. A second scan of the same challan is refused.',
  reads:['Approved POs due','Challan + e-way bill'],api:[['Post receipt','POST /api/v1/purchase/grns (Idempotency-Key = challan)'],['Stock','GET /api/v1/inventory/stock']],
  states:['nothing due','due, not arrived','at the gate','received, held for QC','duplicate scan refused'],rules:['Receipt only against an approved PO','Same challan twice = same idempotency key = nothing posted','Received stock is held until inspection releases it'],
  render(){if(!S.po||S.po.status!=='approved')return head('Gate','Receiving against purchase orders.')+waitFor(4,'Nothing is on its way yet');const s=SUP[S.po.sup];
    if(!S.grn)return `${head('Expected delivery',`${NEED_QTY} castings from ${esc(s.name)}, promised for ${dmyy(S.po.promised)}.`)}${empty('truck','The castings aren’t here yet',`${esc(s.short)} is pouring them now. Skip to the day they arrive; the demo moves its calendar forward.`,`<button class="btn pri" data-a="truck">${I('clock')}Skip to ${dmy(S.po.promised)}: the truck is at the gate</button>`)}`;
    const g=S.grn;const steps=[['Challan scanned at the gate',g.pending?'Waiting for the scan':stamp(g.at)+' · '+g.no,g.pending?'now':'done'],['Stock posted, held for inspection',g.pending?'After the scan':`+${NEED_QTY} in bin ${SHORT.bin} · can’t be issued yet`,g.pending?'':'done'],['Incoming inspection',S.inspection==='pass'?'Passed · 5 sampled':g.pending?'After receipt':'Latha checks the lot',S.inspection==='pass'?'done':g.pending?'':'now'],['Released to production',S.inspection==='pass'?'All '+NEED_QTY+' usable':'After inspection',S.inspection==='pass'?'done':'']];
    return `${head('Receive '+S.po.no,'One scan moves stock, valuation and the supplier’s on-time record. Inspection decides whether the stock can be used.')}
    <div class="two"><div style="display:flex;flex-direction:column;gap:12px;min-width:0"><div class="card"><div class="scanbox ${g.pending?'':'ok'}"><div class="doc"><b>DELIVERY CHALLAN · ${esc(s.short.toUpperCase())}</b><i></i><i class="w"></i><i></i><span>${NEED_QTY} × ${SHORT.code} · ${S.po.no}</span><i class="w"></i></div><span class="beam"></span>${g.pending?'':`<span class="okm">${I('check')}</span>`}</div>
      ${kv('Against','<span class="mono">'+S.po.no+'</span>')}${kv('Ordered / delivered',NEED_QTY+' / '+NEED_QTY+' nos')}${kv('On time?','<span style="color:var(--green-ink)">Yes · '+dmy(S.po.promised)+'</span>')}
      <div class="btns"><button class="btn ${g.pending?'pri':'gh'}" data-a="scan">${I('scan')}${g.pending?'Scan the challan':'Scan it again'}</button></div>${!g.pending?`<p class="note">Try it: a second scan is refused, not doubled.${S.dupScans?` Refused ${S.dupScans}×.`:''}</p>`:''}</div></div>
    <div style="display:flex;flex-direction:column;gap:12px;min-width:0"><div class="card"><h4>What happened</h4>${pipeHtml(steps)}${!g.pending&&S.inspection!=='pass'?`<button class="btn pri block" data-go="t.qc">${I('shield')}Inspect the lot</button>`:''}</div>${!g.pending?recordDelta(S.po.sup):''}</div></div>`}});
def('t.qc',{role:'stores',title:'Incoming inspection',route:'/quality/inspections/:id',purpose:'Latha samples the lot against the written quality plan the supplier saw before quoting. Passing releases stock and adds the pieces to the supplier’s record; rejecting holds the lot and raises a finding.',
  reads:['Quality plan QP-BDY-150 rev 2','GRN lot'],api:[['Create inspection','POST /api/v1/quality/inspections'],['Readings','POST /api/v1/quality/inspections/{id}/readings'],['Disposition','POST /api/v1/quality/inspections/{id}/disposition'],['Finding','POST /api/v1/quality/findings']],
  states:['nothing to inspect','readings in','passed + released','rejected → finding'],rules:['The plan was in the RFQ, so a reject is a broken promise','Rejected pieces count against the supplier’s record','Stock on hold can’t be issued'],
  render(){if(!S.grn||S.grn.pending)return head('Incoming inspection','Sampling against the quality plan.')+waitFor(5,'No lot waiting for inspection');const ok=S.inspection==='pass';
    return `${head('Inspect '+S.grn.no,`Sample of 5 from ${NEED_QTY} against ${QPLAN.no}. The supplier saw these limits before quoting.`)}
    <div class="two"><div class="card"><div class="scx"><table class="tbl"><thead><tr><th>Check</th><th>Limit</th><th>Found</th><th></th></tr></thead><tbody>${QPLAN.checks.map(c=>`<tr><td><b>${esc(c[0])}</b></td><td>${esc(c[1])}</td><td class="num">${esc(c[2])}</td><td>${pill('ok')}</td></tr>`).join('')}</tbody></table></div>
      ${ok?`<div class="card ok"><div class="row sb"><b style="color:var(--ink)">Lot passed and released</b>${pill('approved')}</div><p class="sub">All ${NEED_QTY} castings can be issued to production.</p></div>`:`<div class="btns"><button class="btn pri" data-a="inspect" data-res="pass">${I('check')}Pass the lot</button><button class="btn gh" data-a="inspect" data-res="reject">Reject the lot</button></div>`}</div>
    ${recordDelta(S.po.sup)}</div>`}});
def('t.stock',{role:'stores',title:'Stock',route:'/inventory/stock',purpose:'Parts for the pump by bin, with what is free and what is on quality hold. Every movement goes through the one stock ledger.',
  reads:['Stock by bin','Quality holds'],api:[['Stock','GET /api/v1/inventory/stock'],['Ledger entry','POST /api/v1/stock/entries']],states:['free','on hold','issued'],rules:['Only the stock ledger moves stock','Held stock can’t be issued'],
  render(){const iss=!!S.wo;return `${head('Stock','Parts for '+ORDER.code+', by bin. One ledger moves all of it.')}
    <div class="scx"><table class="tbl"><thead><tr><th>Part</th><th>Bin</th><th class="r">Free</th><th class="r">On hold</th><th class="r">Issued to WO</th></tr></thead><tbody>${BOM.map(b=>{const add=b===SHORT&&S.grn&&!S.grn.pending?NEED_QTY:0;const hold=b===SHORT&&add&&S.inspection!=='pass'?NEED_QTY:0;const i2=iss?ORDER.qty*b.per:0;const free=b.stock+add-hold-i2;
      return `<tr class="${b===SHORT&&S.bumped?'bump':''}"><td><b>${esc(b.name)}</b><div class="s mono">${b.code}</div></td><td class="mono">${b.bin}</td><td class="r num">${nos(free)}</td><td class="r num">${hold?`<span class="pill st-pending">${hold} QC</span>`:'—'}</td><td class="r num">${i2?nos(i2):'—'}</td></tr>`}).join('')}</tbody></table></div>`}});
def('t.rec',{role:'stores',title:'Supplier records',route:'/purchase/network/suppliers',purpose:'The same earned records Priya ranks on. Stores and quality write them; nobody types them.',reads:['Receipts and inspections'],api:[['Performance','GET /api/v1/purchase/network/suppliers/{id}/performance']],states:['proven','unproven'],rules:['Written by the gate and the inspection, read by the ranking'],
  render(){return head('Supplier records','Written at this gate. Read by the ranking.')+scorecard()}});

/* ================= SHOP FLOOR (Suresh, phone) ================= */
const WSTEPS=[['Release','factory'],['Output','plus'],['Test','shield'],['Ship','truck']];
def('m.jobs',{role:'floor',title:'XELOR Floor',kn:'Assembly 1 · shift A',route:'/jobs',purpose:'The supervisor’s job queue. A work order appears only when every part is on the shelf, so the floor never starts a job it can’t finish.',
  reads:['Released and releasable work orders'],api:[['Work orders','GET /api/v1/production/orders?line=ASSY-1']],states:['blocked by a short part','ready to release','in progress','done'],rules:['Release needs every BOM part available','Each job shows why it is blocked'],
  render(){const ready=S.inspection==='pass',w=S.wo;return `<div class="xp-strip"><span>${I('factory')} Assembly 1 · 3 operators on shift</span><span class="mono">${tm()}</span></div>
    <div class="kpis" style="grid-template-columns:repeat(3,minmax(0,1fr))"><div class="kpi hl"><b>${ready&&!(w&&w.status==='done')?1:0}</b><span>to work on</span></div><div class="kpi"><b>${w&&w.status==='done'?3:2}</b><span>done this week</span></div><div class="kpi"><b>0</b><span>scrap</span></div></div>
    <div class="eyb">Jobs · Assembly 1</div>
    <button class="xp-task ${w&&w.status==='done'?'done':''}" data-go="m.wo"><div class="row sb"><b>WO-2627-0918 · ${ORDER.qty} pumps</b>${w&&w.status==='done'?pill('ok'):ready?`<span class="sla">${I('clock')} ${w?'in progress':'ready to release'}</span>`:pill('awaiting')}</div><span>${esc(ORDER.item)} · for ${ORDER.no}</span><span class="mono">${ready?'All 6 parts on the shelf':`Blocked: ${NEED_QTY} pump bodies short`}</span></button>
    <div class="xp-task done"><div class="row sb"><b>WO-2627-0911 · 40 pumps</b>${pill('ok')}</div><span>Pump, 4 in · shipped 26 Sep</span></div>
    <div class="xp-task done"><div class="row sb"><b>WO-2627-0904 · 25 pumps</b>${pill('ok')}</div><span>Pump, 6 in · shipped 22 Sep</span></div>`}});
def('m.wo',{role:'floor',title:'Work order',kn:'WO-2627-0918',route:'/jobs/:id',nav:'m.wo',purpose:'One work order, start to finish on the phone: release and issue materials, record output, then the final test that quality signs. Each step unlocks the next.',
  reads:['Work order + BOM','Stock available','Final test plan'],api:[['Release + issue','POST /api/v1/production/orders/{id}/issue'],['Complete operation','POST /api/v1/production/orders/{id}/operations/{seq}/complete'],['Final inspection','POST /api/v1/quality/inspections/{id}/complete'],['Complete WO','POST /api/v1/production/orders/{id}/complete']],
  states:['blocked','ready','issued','made','testing','done'],rules:['Materials leave stores only through the stock ledger','Every pump is tested; all four checks must pass','Output can’t exceed the order quantity'],
  render(){const w=S.wo;const hd=`<div class="xp-farmer"><span class="av">${I('factory')}</span><div class="grow"><b>${ORDER.qty} × ${esc(ORDER.item)}</b><span>${w?w.no:'WO-2627-0918'} · for ${ORDER.no}</span></div><span class="badge">${w?w.made:0}/${ORDER.qty}</span></div>`;
    if(S.inspection!=='pass')return hd+empty('lock','Can’t be released yet',S.planRun?`${NEED_QTY} pump bodies are short. The work order releases only when every part is on the shelf.`:'Planning hasn’t run for this order yet.',`<button class="btn xp sm" data-go="${nextStep().go}">${esc(nextStep().b)}</button>`);
    const st=!w?0:w.status==='issued'?1:w.status==='made'?2:3;
    const stepper=`<div class="xp-steps" style="grid-template-columns:repeat(4,minmax(0,1fr))">${WSTEPS.map(([l,ic],i)=>`<button class="${i===st?'cur':''} ${i<st?'ok':''}" disabled><span>${i<st?I('check'):I(ic)}</span>${l}</button>`).join('')}</div>`;
    let body='';
    if(st===0)body=`<div class="card"><h4>Release and issue materials</h4><p class="sub">Six parts for ${ORDER.qty} pumps leave stores through the stock ledger.</p>${BOM.map(b=>kv(esc(b.name),nos(ORDER.qty*b.per)+' nos')).join('')}<button class="btn xp block" data-a="release">${I('factory')}Release and issue</button></div>`;
    if(st===1)body=`<div class="card"><div class="counter"><b>0<small> / ${ORDER.qty}</small></b></div><p class="center sub">Materials issued. Record output when assembly is done.</p><button class="btn xp block" data-a="output">${I('plus')}Record ${ORDER.qty} made</button></div>`;
    if(st===2)body=`<div class="card"><div class="counter"><b>${cu(w.made)}<small> / ${ORDER.qty}</small></b></div><p class="center sub">0 scrap · assembled on Assembly 1</p></div>
      <div class="card" style="gap:0"><h4 style="margin-bottom:4px">Final test · every pump</h4>${FTESTS.map((c,i)=>`<div class="check" role="checkbox" tabindex="0" aria-checked="${S.tests[i]}" data-a="test" data-i="${i}"><span class="cb">${I('check')}</span><div><b>${esc(c[0])}</b><span>${esc(c[1])}</span></div></div>`).join('')}</div>
      <button class="btn xp block" data-a="finalTest" ${S.tests.every(Boolean)?'':'disabled'}>${I('shield')}Pass final test</button>`;
    if(st===3)body=`<div class="tick" style="background:var(--deep);color:#f0c95f">${I('check')}</div><div class="center"><h3 class="h3">${ORDER.qty} pumps ready to ship</h3><p class="sub">${days(clockDate(),ORDER.due)} days before ${dmy(ORDER.due)} · handed to dispatch</p></div><div class="card">${kv('Made',ORDER.qty+' of '+ORDER.qty)}${kv('Scrap','0')}${kv('Final test','4 of 4 checks · all pumps')}</div>`;
    return hd+stepper+body}});
def('m.mat',{role:'floor',title:'Materials',kn:'issued to WO-2627-0918',route:'/jobs/:id/materials',nav:'m.mat',purpose:'What left the store for this job and what is left on the shelf. Stock goes down as parts are issued, never by a manual adjustment.',
  reads:['Stock ledger entries for the WO'],api:[['Ledger','GET /api/v1/inventory/stock?wo={id}']],states:['nothing issued','issued'],rules:['Only the ledger moves stock'],
  render(){const iss=!!S.wo;return `<div class="card" style="gap:0">${BOM.map(b=>{const i2=iss?ORDER.qty*b.per:0,have=b.stock+(b===SHORT&&S.inspection==='pass'?NEED_QTY:0);return `<div class="kv"><span><b style="color:var(--ink)">${esc(b.name)}</b><span class="mono" style="display:block;font-size:10px">${b.code}</span></span><b>${i2?nos(i2)+' issued':'—'}<span class="sub" style="display:block;font-weight:500">${nos(have-i2)} left</span></b></div>`}).join('')}</div>${iss?'':`<p class="note center">Nothing issued yet. Release the work order first.</p>`}`}});

/* ================= ACCOUNTS (laptop, dark console) ================= */
def('a.dispatch',{role:'acct',title:'Dispatch & invoice',route:'/sales/orders/SO-2627-0291/dispatch',purpose:'One step writes the delivery note, the GST invoice, the receivable and the ledger voucher together, or none of them. Then the IRN and e-way bill make the invoice valid.',
  reads:['Finished goods','Customer GSTIN + place of supply','Order price'],api:[['Dispatch (one transaction)','POST /api/v1/sales/orders/{id}/dispatch (Idempotency-Key)'],['E-invoice','POST /api/v1/integration/einvoice/submit'],['Fetch IRN','POST /api/v1/integration/einvoice/{invoiceRef}/fetch']],
  states:['nothing to ship','draft','writing','issued','IRN attached'],rules:['Four records in one transaction, or none','IGST when goods cross a state','IRN and e-way bill are simulated; no GST provider connected'],
  render(){if(!S.wo||S.wo.status!=='done')return head('Dispatch & invoice','Delivery note, GST invoice, receivable and ledger entry, together.')+waitFor(6,'Nothing is ready to ship');
    const d=S.dispatch,date=d?d.at.slice(0,10):addDays(S.po.promised,6);const chks=[['Stock issued: 80 pumps out of finished goods','DN-2627-0288'],['GST invoice raised with IGST','INV-2627-0781'],['Receivable opened, due in 30 days',inr(INVOICE_TOTAL)],['Ledger voucher posted','SV-0781']];
    return `${head('Dispatch and invoice','One step writes all four records, or none of them. There’s no half-finished paperwork to chase.')}
    <div class="two"><div class="docsheet"><div class="dh"><div><h4>Tax invoice</h4><div class="no">INV-2627-0781 · ${dmyy(date)}</div></div>${d&&d.irn?stampHtml('Shipped',S.stamped[7]||S.clock,false,true,S.justStamped===7):d?tp('Issued','ok'):tp('Draft')}</div>
      <div class="parties"><div><small>From</small><b>${esc(FACTORY.name)}</b><br>${FACTORY.town}<br><span class="mono" style="font-size:11px">${FACTORY.gstin}</span></div><div><small>Bill and ship to</small><b>${esc(CUSTOMER.name)}</b><br>${esc(CUSTOMER.town)}<br><span class="mono" style="font-size:11px">${CUSTOMER.gstin}</span></div></div>
      <div class="scx"><table class="tbl"><tbody><tr><td>${ORDER.qty} × ${esc(ORDER.item)} <span class="s">HSN ${ORDER.hsn}</span></td><td class="r num">${inr(TAXABLE)}</td></tr><tr><td class="s">IGST 18% · place of supply Andhra Pradesh</td><td class="r num">${inr(IGST)}</td></tr><tr class="tot"><td>Total</td><td class="r num">${inr(INVOICE_TOTAL)}</td></tr>
      <tr><td class="s">IRN</td><td class="r mono" style="font-size:11px">${d&&d.irn?d.irn+'…':'—'}</td></tr><tr><td class="s">E-way bill</td><td class="r mono" style="font-size:11px">${d&&d.ewb?d.ewb:'—'}</td></tr></tbody></table></div></div>
    <div style="display:flex;flex-direction:column;gap:12px;min-width:0"><div class="card"><div class="row sb"><h4>One transaction</h4><span class="sub">${d?(d.running?'Writing…':'All four written together'):'Nothing written yet'}</span></div><div class="checks">${chks.map(c=>`<div class="chk ${d&&!d.running?'on':''}" data-chk><span class="c">${I('check')}</span>${esc(c[0])}<small>${esc(c[1])}</small></div>`).join('')}</div>${!d?`<button class="btn pri block" data-a="dispatch">${I('truck')}Dispatch and invoice</button>`:''}</div>
    ${d&&!d.running?`<div class="card"><h4>IRN and e-way bill</h4>${d.irn?`<div class="row" style="flex-wrap:wrap;gap:6px">${tp('IRN attached','ok')}${tp('E-way bill valid 2 days · '+CUSTOMER.km+' km','ok')}${tp('Simulated','warn')}</div>`:`<p class="sub">Without an IRN the invoice isn’t valid and the customer loses their input credit.</p><button class="btn pri" data-a="irn">${I('shield')}Get IRN and e-way bill</button>`}</div>`:''}</div></div>`}});
def('a.books',{role:'acct',title:'Ledger',route:'/accounts/vouchers?ref=SO-2627-0291',purpose:'What this one order left in the books. Every line was written by an event, a dispatch or a receipt, never typed as a journal, so it reconciles with the floor. Then the order closes and the last station is stamped.',
  reads:['Vouchers linked to the order','Payables and the MSME clock'],api:[['Vouchers','GET /api/v1/accounts/vouchers?ref={orderNo}'],['Trial balance','GET /api/v1/accounts/trial-balance'],['Reverse (never edit)','POST /api/v1/accounts/vouchers/{id}/reverse']],
  states:['nothing posted','posted','payables being built','closed'],rules:['A mistake is reversed by a new voucher, never edited','MSME supplier: pay within 45 days of acceptance or lose the deduction (43B(h))','Supplier invoices and payables are being built'],
  render(){if(!S.dispatch||!S.dispatch.irn)return head('Ledger','What this order leaves in the books.')+waitFor(7,'Nothing posted for this order yet');
    const inv=S.dispatch.at.slice(0,10),recvDue=addDays(inv,CUSTOMER.terms),acc=S.po.promised,payDue=addDays(acc,45),shipped=inv;
    return `${head('What '+ORDER.no+' left in the books','Every line was written by an event, never typed as a journal. That’s why it reconciles with the floor.')}
    <div class="kpis"><div class="kpi hl"><b>${cu(INVOICE_TOTAL,'inr')}</b><span>customer owes · due ${dmyy(recvDue)}</span></div><div class="kpi"><b>${cu(S.po.total,'inr')}</b><span>you owe the foundry · by ${dmyy(payDue)}</span></div><div class="kpi"><b>${days('2026-09-30',inv)} days</b><span>order to dispatch</span></div><div class="kpi"><b>${days(inv,ORDER.due)} days</b><span>shipped early</span></div></div>
    <div class="scx"><table class="tbl"><thead><tr><th>Date</th><th>Entry</th><th class="r">Debit</th><th class="r">Credit</th><th>Source</th></tr></thead><tbody>
      <tr><td class="s">${dmy(inv)}</td><td>Trade receivable · ${esc(CUSTOMER.name)}</td><td class="r num">${inr(INVOICE_TOTAL)}</td><td></td><td rowspan="3">${tp('Dispatch','ok')} ${tp('Synced to Tally','gold')}</td></tr><tr><td></td><td style="padding-left:28px">Sales</td><td></td><td class="r num">${inr(TAXABLE)}</td></tr><tr><td></td><td style="padding-left:28px">IGST output</td><td></td><td class="r num">${inr(IGST)}</td></tr>
      <tr><td class="s">${dmy(acc)}</td><td>Inventory · pump bodies</td><td class="r num">${inr(S.po.exGst)}</td><td></td><td rowspan="3">${tp('Being built','info')}</td></tr><tr><td></td><td>IGST input</td><td class="r num">${inr(S.po.gst)}</td><td></td></tr><tr><td></td><td style="padding-left:28px">Payable · ${esc(SUP[S.po.sup].name)}</td><td></td><td class="r num">${inr(S.po.total)}</td></tr></tbody></table></div>
    ${msmeClock(acc,payDue)}
    ${S.closed?`<div class="closing"><span class="eyb" style="color:#f0c95f">Closed · ${dmy(S.stamped[8].slice(0,10))}</span><h4>Typed once. Carried through nine stations.</h4><p>The order was entered on 30 Sep. XELOR found the short part, the network found a price, the owner signed on his phone, and the pumps shipped ${days(shipped,ORDER.due)} days before they were due.</p>
      <div class="summary"><div><b>1</b><small>time the order was typed</small></div><div><b>${days('2026-09-30',shipped)} days</b><small>from order to dispatch</small></div><div><b>${S.rfq.to.length}</b><small>suppliers asked, ranked in seconds</small></div><div><b>${S.log.length}</b><small>entries in the audit trail</small></div><div><b>+1 on time</b><small>on ${esc(SUP[S.po.sup].short)}’s record, counted at the gate</small></div><div><b>${Math.round((KAVERI_REC.onTimeN+1)/(KAVERI_REC.orders+1)*100)}%</b><small>Kaveri’s own on-time record, ${KAVERI_REC.orders+1} orders</small></div></div></div>`
      :`<div class="card"><h4>Close the order</h4><p class="sub">Everything is shipped, invoiced and posted. Closing stamps the last station on the route card.</p><button class="btn pri" data-a="close">${I('check')}Close ${ORDER.no}</button></div>`}`}});
def('a.audit',{role:'acct',title:'Audit trail',route:'/admin/audit',purpose:'Every event on the order as a hash chain: each entry carries the hash of the one before, so a changed or deleted entry breaks every link after it. Verify recomputes the chain.',
  reads:['Audit log (append-only)'],api:[['Verify chain','POST /api/v1/admin/audit/verify'],['Anchor daily root','POST /api/v1/admin/audit/anchor'],['Audit pack','GET /api/v1/admin/audit/pack']],
  states:['empty','chain','verified','broken (tamper detected)'],rules:['Append-only for everyone, including the schema owner','A correction is a new entry, never an edit','The day’s root hash is anchored'],
  render(){const ev=[...S.log].reverse();let prev='0'.repeat(64);
    return `${head('Audit trail',`${ev.length} entr${ev.length===1?'y':'ies'} on ${ORDER.no}, oldest first. Each links to the hash of the one before.`,ev.length?`<button class="btn ${S.verified?'gh':'pri'} sm" data-a="verify">${I('shield')}${S.verified?'Verified · run again':'Verify chain'}</button>`:'')}
    ${ev.length?`<div class="card"><div class="xp-chain">${ev.map((l,i)=>{const h=hx(prev+l.what+l.at);const row=`<div class="blk" style="animation-delay:${Math.min(i,12)*.04}s"><span class="bi">${i+1}</span><div class="grow"><b>${esc(l.what)}</b><span>${esc(l.who)} · ${stamp(l.at)}</span><code>prev ${hshort(prev)} → ${hshort(h)}</code></div></div>`;prev=h;return row}).join('')}</div></div><p class="note">Append-only. The day’s root hash is anchored at 23:59 IST.${S.verified?' Last verification: intact.':''}</p>`:empty('lock','Nothing recorded yet','Every action on the order writes an entry here.')}`}});

/* Example-view map: [steps needed for the real view, steps to run for the example, optional extra setup] */
const PV={'p.plan':[1,2],'p.net':[2,4],'p.po':[5,5],'p.log':[1,13],
  's.chat':[3,6],'s.quote':[3,3],'w.inbox':[5,5],'w.po':[5,5],'w.today':[1,13],
  't.gate':[6,7],'t.qc':[7,7],'m.wo':[8,9,()=>{A.output();S.tests=[true,true,false,false]}],'m.mat':[8,9],
  'a.dispatch':[10,12],'a.books':[12,13],'a.audit':[1,13]};
